生成查询代码
SELECT s.A_STOCKCODE AS `股票代码`, s.A_STOCKSNAME AS `股票简称`, SUM(s.TOT_ACCUM_DIV) / 100000000 AS `最近三年累计现金分红(亿元)` FROM STK_DIV_STAT s JOIN GET_A_SEC_CODE c ON s.COMCODE = c.COMCODE AND c.ISVALID = 1 WHERE s.ISVALID = 1 AND s.DIV_YEAR >= 2023 AND s.DIV_YEAR <= 2025 AND s.TOT_ACCUM_DIV IS NOT NULL GROUP BY s.A_STOCKCODE, s.A_STOCKSNAME ORDER BY `最近三年累计现金分红(亿元)` DESC LIMIT 5;
